// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.llm.providerimport com.roshan.persona.brain.stream.CancellationTokenimport com.roshan.persona.common.Result/** * NOUS — Cloud LLM provider interface. * * Wraps any cloud LLM API (OpenAI, Anthropic, Gemini, Groq, OpenRouter, * user-hosted vLLM/Ollama, etc.) behind a unified interface. * * Real HTTP implementation lives in :feature:llm (Module 4) using OkHttp + * Retrofit. Brain uses this interface to stay testable without network calls. * * ## Lifecycle * *   1. **Validation** — [validateCredentials] (optional, user-triggered) tests *      whether the API key works. Used by Settings → AI Models → Test Connection. * *   2. **Model discovery** — [listAvailableModels] (optional) returns the *      provider's model catalog. Used by Settings → AI Models → Refresh Models. * *   3. **Generation** — [generate] runs a chat completion with streaming. * *   4. **Embedding** — [embed] (optional, not all providers support this). * * ## Pluggability * * User can add ANY provider that speaks one of the supported [ApiProtocol]s. * The registry creates a [CloudLlmProvider] instance from the user's config — * no code change needed when a new provider launches in the market. * * ## Privacy * *   - Provider never sees the API key directly — it's looked up via *     [com.roshan.persona.brain.skill.CredentialVaultInterface] at call time. *   - All PII in the prompt is scrubbed before sending (use *     [com.roshan.persona.brain.llm.context.ContextInjector.scrubForCloud]). *   - Calls are HTTPS-only (enforced by [CloudProviderConfig.baseUrl] init). *   - Certificate pinning applied if [CloudProviderConfig.certPins] is non-empty. * * @see <a href="docs/spec/module2-spec-review.pdf">§8 Layer 4</a> */interface CloudLlmProvider {    /** Stable unique ID (matches [CloudProviderConfig.id]). */    val providerId: String    /** Display name (matches [CloudProviderConfig.displayName]). */    val displayName: String    /** The config this provider was created from. */    val config: CloudProviderConfig    /**     * Whether this provider is currently usable.     *     * False if:     *   - [CloudProviderConfig.isEnabled] is false (user hasn't opted in)     *   - API key alias is not set in CredentialVault     *   - Device is offline (for cloud providers — local providers skip this check)     */    val isAvailable: Boolean    /**     * Generate text from a prompt with streaming token callback.     *     * The [prompt] should be ALREADY scrubbed of PII (caller's responsibility     * — see [com.roshan.persona.brain.llm.context.ContextInjector.scrubForCloud]).     *     * **Barge-in support**: The caller can pass a [CancellationToken]. If     * cancelled (user interrupts), the underlying HTTP call is aborted     * via [CancellableHttpCall.cancel]. This prevents wasted API costs     * and stops streaming immediately.     *     * @param prompt the full prompt (system + context + user input), PII-scrubbed     * @param model target model ID (must be in [CloudProviderConfig.availableModels])     * @param config generation parameters     * @param onToken called for each generated token (for streaming UI)     * @param cancellationToken optional — if cancelled, aborts the HTTP call     * @return [GenerationResult] with full text + metadata     */    suspend fun generate(        prompt: String,        model: String,        config: GenerationConfig,        onToken: (String) -> Unit,        cancellationToken: CancellationToken? = null,    ): Result<GenerationResult>    /**     * Generate embedding for a text (for semantic cache).     *     * Not all cloud providers support embeddings. Returns Failure if unsupported.     *     * @return 384-dim float vector (or provider's native dimension)     */    suspend fun embed(text: String, model: String? = null): Result<FloatArray>    /**     * Validate that the API key works.     *     * Used by Settings → AI Models → Test Connection. Makes a minimal API     * call (e.g., GET /models for OpenAI-compatible, /v1/models for Anthropic)     * to check authentication without consuming tokens.     *     * @return Success if credentials valid, Failure with error otherwise     */    suspend fun validateCredentials(): Result<Unit>    /**     * List models available on this provider.     *     * Calls the provider's /models endpoint (or equivalent) to fetch the     * current model catalog. Used to populate the model picker in Settings.     *     * @return list of [ModelInfo], or Failure if call fails     */    suspend fun listAvailableModels(): Result<List<ModelInfo>>}/** * Information about a model offered by a cloud provider. */data class ModelInfo(    /** Provider-specific model ID (e.g., "gpt-4o", "claude-3-5-sonnet-20241022"). */    val id: String,    /** Human-readable name (e.g., "GPT-4o"). */    val displayName: String,    /** Maximum context length in tokens. */    val contextLength: Int,    /** Whether this model supports streaming responses. */    val supportsStreaming: Boolean,    /** Whether this model supports embeddings. */    val supportsEmbeddings: Boolean,    /** Whether this model supports tool/function calling. */    val supportsToolCalling: Boolean,    /** Whether this model supports vision (image input). */    val supportsVision: Boolean,    /** Pricing (USD per 1k tokens). */    val pricing: Pricing,    /** When this model was released (epoch millis, 0 if unknown). */    val releasedAtEpochMs: Long = 0L,    /** Provider's description of this model. */    val description: String? = null,) {    companion object {        /**         * Sentinel "unknown" model — used when provider doesn't return         * model details (e.g., self-hosted vLLM with no /models endpoint).         */        val UNKNOWN = ModelInfo(            id = "unknown",            displayName = "Unknown Model",            contextLength = 4_096,            supportsStreaming = true,            supportsEmbeddings = false,            supportsToolCalling = false,            supportsVision = false,            pricing = Pricing.FREE,        )    }}